INSERT INTO `acciones_catalogo` VALUES (1,'Poda de Formación','Corte de ramas secas, elevación de copa y despeje de pantallas urbanas o luminarias.'),(2,'Despunte','Reducción controlada de la copa y altura del árbol para mitigar riesgos o interferencias.'),(3,'Derribe Controlado','Tala o eliminación total del espécimen debido a muerte (árbol seco), pudrición, inclinación severa o daño estructural irreversible.'),(4,'Emergencia','Intervención inmediata por árbol caído o con peligro inminente de colapso.'),(5,'Poda de Raíces','Corte controlado de raíces que causan daños a pavimentos, aceras o estructuras cercanas.'),(6,'Extracción de Tocón','Remoción del remanente del tronco (tocón) y raíces superficiales para evitar rebrotes o plagas.'),(7,'Poda General y otros','Ejecución de múltiples tipos de poda combinada, sujeto al diagnóstico del criterio técnico en campo.'),(8,'No Determinado','Pendiente de evaluación técnica en el lugar.');
/*!40000 ALTER TABLE `acciones_catalogo` ENABLE KEYS */;
